// Guard: the headline figures in docs/free-toolkit.md must match the corpus.
//
// WHY THIS EXISTS
// ---------------
// free-toolkit.md opens by claiming "229 distinct tools, of which 198 are free in
// some form and 31 are things you already have". None of those three numbers came
// from the data. The corpus holds 237 distinct tools, the site's own costTone()
// classifies 219 free / 16 freemium / 2 paid, and the "31 things you already have"
// sat directly above a list of seven examples.
//
// The page also says it "is generated by reading the ## Tools for This Phase
// tables" — but no generator existed. A document that claims to be generated and
// is not will drift silently, which is exactly what happened.
//
// So this guard does not regenerate the prose. It reads the numbers the page
// states and asserts they equal the numbers the corpus produces, using the same
// parser the site uses (the generated JSON) and the same classifier the site uses
// (costTone, ported below and kept in step by test-cost-tone.mjs).
//
// Run: node scripts/audit-free-toolkit.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const GEN = path.join(ROOT, 'learning-site', 'src', 'data', 'generated');
const DOC = path.join(ROOT, 'docs', 'free-toolkit.md');

/**
 * Verbatim port of costTone() from learning-site/src/data/tools.js.
 *
 * Duplicated rather than imported because the site's copy is an ES module inside
 * the Vite app and reading it from a plain Node guard would mean a transform step.
 * test-cost-tone.mjs already asserts the two agree, so this cannot drift alone.
 */
function costTone(cost) {
  const c = String(cost || '').toLowerCase();
  if (/\bfree\b|\bopen[- ]?source\b|\bmit\b|\bstandard library\b/.test(c)) {
    if (/freemium/.test(c)) return 'freemium';
    return 'free';
  }
  if (/freemium/.test(c)) return 'freemium';
  if (/\bpaid\b|\bpay-per-token\b|\bsubscription\b|\bbilled\b/.test(c)) return 'paid';
  return 'freemium';
}

const problems = [];
const fail = (msg) => problems.push(msg);

// ---------------------------------------------------------------- read corpus

// The generated JSON is gitignored and, in CI, this step runs on a bare checkout
// BEFORE `npm ci` and before the site build — deliberately, because the whole
// point of that gate is that it has no dependencies. So if the JSON is not there,
// build it. `build-content.mjs` with no flags writes the JSON and exits 0 on a
// valid corpus, which is the same code path the site build uses, so this cannot
// diverge from what the site would read.
if (!fs.existsSync(GEN)) {
  const { spawnSync } = await import('node:child_process');
  const built = spawnSync(
    process.execPath,
    [path.join(ROOT, 'scripts', 'build-content.mjs')],
    { encoding: 'utf8' },
  );
  if (built.status !== 0 || !fs.existsSync(GEN)) {
    process.stderr.write(
      'audit-free-toolkit: could not produce the generated JSON.\n' +
        (built.stderr || '') +
        '\n',
    );
    process.exit(2);
  }
}
if (!fs.existsSync(DOC)) {
  process.stderr.write('audit-free-toolkit: docs/free-toolkit.md not found.\n');
  process.exit(2);
}

const tracksRaw = JSON.parse(fs.readFileSync(path.join(GEN, 'tracks.json'), 'utf8'));
const trackList = Array.isArray(tracksRaw) ? tracksRaw : (tracksRaw.tracks ?? []);

let rows = 0;
const allTools = [];
for (const t of trackList) {
  const id = t.id ?? t.slug;
  const f = path.join(GEN, `${id}.json`);
  if (!fs.existsSync(f)) continue;
  const data = JSON.parse(fs.readFileSync(f, 'utf8'));
  for (const p of data.phases ?? []) {
    for (const tool of p.tools ?? []) {
      rows += 1;
      allTools.push(tool);
    }
  }
}

// De-duplicate by name exactly as ToolsLibrary.jsx does (trim + lowercase).
const byName = new Map();
for (const tool of allTools) {
  const key = String(tool.name ?? '').trim().toLowerCase();
  if (!key) continue;
  if (!byName.has(key)) byName.set(key, tool);
}
const distinct = [...byName.values()];
const tones = { free: 0, freemium: 0, paid: 0 };
for (const t of distinct) tones[costTone(t.cost)] += 1;

// ------------------------------------------------------------- read the page

const doc = fs.readFileSync(DOC, 'utf8');

/** Read an integer that the page states next to a phrase. */
function stated(re, label) {
  const m = doc.match(re);
  if (!m) {
    fail(`could not find the stated ${label} in docs/free-toolkit.md`);
    return null;
  }
  return Number(m[1].replace(/,/g, ''));
}

const statedDistinct = stated(/\*\*([\d,]+) distinct tools\*\*/, 'distinct-tool count');
const statedFree = stated(/\*\*([\d,]+) are free\*\*/, 'free count');
const statedFreeTier = stated(/\*\*([\d,]+) are free-tier or freemium\*\*/, 'freemium count');

// ------------------------------------------------------------------- compare

if (statedDistinct !== null && statedDistinct !== distinct.length) {
  fail(
    `docs/free-toolkit.md says ${statedDistinct} distinct tools; the corpus has ${distinct.length}`,
  );
}
if (statedFree !== null && statedFree !== tones.free) {
  fail(
    `docs/free-toolkit.md says ${statedFree} are free; costTone() classifies ${tones.free} as free ` +
      `(and ${tones.freemium} as freemium)`,
  );
}
if (statedFreeTier !== null && statedFreeTier !== tones.freemium) {
  fail(
    `docs/free-toolkit.md says ${statedFreeTier} are free-tier or freemium; costTone() classifies ` +
      `${tones.freemium}`,
  );
}

// The "things you already have" claim is the one that was most wrong, so it gets
// two checks: the header states a number, and a later section states the same
// number above a bulleted list. Both must agree with each other, because the page
// previously said "31" in the header and "31 of the 229" in the body while the
// list beneath held seven items.
const headerHave = doc.match(/\*\*([\d,]+) are things you already have\*\*/);
const bodyHave = doc.match(/^[^\S\n]*([\d,]+) of the ([\d,]+) entries are not tools at all/m);

const listMatch = doc.match(/things you already have\*\*[\s\S]{0,200}?:\n+((?:- [^\n]*\n)+)/);
if (listMatch) {
  const items = (listMatch[1].match(/^- /gm) ?? []).length;
  if (bodyHave) {
    const n = Number(bodyHave[1].replace(/,/g, ''));
    if (n !== items) {
      fail(
        `docs/free-toolkit.md says ${n} things "are not tools at all" but the list beneath ` +
          `holds ${items} items`,
      );
    }
  }
} else {
  fail('could not read the "things you already have" list to check its count');
}

if (headerHave && bodyHave) {
  const a = Number(headerHave[1].replace(/,/g, ''));
  const b = Number(bodyHave[1].replace(/,/g, ''));
  if (a !== b) {
    fail(`the header says ${a} "things you already have" but the body says ${b} — they must agree`);
  }
}
if (headerHave) {
  const a = Number(headerHave[1].replace(/,/g, ''));
  // The header's claim is a subset of the corpus, so it can never exceed it.
  if (a > distinct.length) {
    fail(`the header claims ${a} things you already have, more than the ${distinct.length} tools that exist`);
  }
}

// The body must not re-state a stale total either.
if (bodyHave) {
  const total = Number(bodyHave[2].replace(/,/g, ''));
  if (total !== distinct.length) {
    fail(`the body says "of the ${total} entries"; the corpus has ${distinct.length}`);
  }
}

// The page must never claim a tool count that no phase table can produce.
if (statedDistinct !== null && statedDistinct > distinct.length) {
  fail(
    `${statedDistinct} is greater than every tool named in the corpus (${distinct.length})`,
  );
}

// -------------------------------------------------------------------- report

if (problems.length) {
  process.stderr.write('audit-free-toolkit: FAILED\n');
  for (const p of problems) process.stderr.write(`  - ${p}\n`);
  process.stderr.write(
    `\nCorpus truth: ${rows} rows, ${distinct.length} distinct tools ` +
      `(${tones.free} free, ${tones.freemium} freemium, ${tones.paid} paid).\n`,
  );
  process.exit(1);
}

process.stdout.write(
  `\u2713 free-toolkit figures match the corpus \u2014 ${rows} rows, ${distinct.length} distinct ` +
    `(${tones.free} free, ${tones.freemium} freemium, ${tones.paid} paid)\n`,
);
